<style scoped lang="css">
.feature {
  background-color: #222224;
  padding-block: 104px;
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 50px;
}

.feature-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  line-height: 1.2;
  color: #fbfbfb;
  justify-content: space-between;
}

.feature-icon {
  margin-bottom: 20px;
  color: var(--color-accent);
}

.feature-card h2 {
  margin: 0 0 16px;
  font-size: 20px;
  font-weight: 400;
}

.feature-card p {
  max-width: 320px;
  margin: 0;
  font-size: 14px;
  font-weight: 300;
  opacity: 0.7;
}

@media (max-width: 1599px) {
  .feature {
    padding-block: 48px 64px;
  }

  .feature-grid {
    grid-template-columns: 1fr;
    gap: 48px;
  }
}

@media (max-width: 767px) {
  .feature {
    padding-block: 48px 81px;
  }

  .feature-grid {
    gap: 46px;
  }
}
</style>
